2	/**
3	 * extract_directive.ts — Extract the next-agent directive from the first
4	 * command-like line of the agent's final text output.
5	 *
6	 * Accepts a standalone "/engineer" line and the common
7	 * markdown-mangled form "/`engineer`". A candidate is only accepted if it
8	 * names a real agent (a matching .md file exists in --def-dir) -- this
9	 * guards against false positives like a model writing "/agent reviewer"
10	 * (matching "agent", not a real agent name) instead of the expected
11	 * "/reviewer", which would otherwise dispatch a doomed-to-fail run for a
12	 * non-existent agent definition.
13	 *
14	 * That tolerance stays even though the prompt now states the line must be bare.
15	 * It was considered for removal on the theory that a strict reader would force
16	 * the prompt to be obeyed, but the two failures fix nothing in common: a
17	 * backtick makes a real handoff disappear, while the failure worth preventing
18	 * was a directive written alongside a conclusion that needed none. Only
19	 * the exclusivity of the outcome prevents that one, and it is stated where the
20	 * agent decides. Strictness here would cost handoffs and buy nothing.
21	 *
22	 * Usage: extract_directive.ts --output-file atomaton_output.txt --def-dir DIR
23	 * Writes `directive=<name-or-empty>` to $GITHUB_OUTPUT.
24	 */
25	import { existsSync, readFileSync, appendFileSync } from "node:fs";
26	import { join } from "node:path";
27	import { parseArgs } from "node:util";
28	import { AGENT_NAME_PATTERN } from "../../domain/work/agent-name.ts";
29	import { lineForms } from "../../domain/work/comment-command.ts";
30	import { defineScript } from "./lib/script-ref.ts";
31	
32	export interface ExtractDirectiveArgs {
33	  "output-file": string;
34	  "def-dir": string;
35	}
36	
37	export const ref = defineScript<ExtractDirectiveArgs>(import.meta.url);
38	
39	const COMMAND_RE = new RegExp(`^\\/(${AGENT_NAME_PATTERN})$`);
40	
41	/**
42	 * Whether a definition exists for `name`, which is what makes a name dispatchable.
43	 *
44	 * The same check `extractDirective` makes before accepting a line, exposed because
45	 * a name can arrive as a bare value rather than as text to be read -- a person's
46	 * command carries the name it typed, and it has to clear the same bar a line does.
47	 * A name with no definition would fail at `gh workflow run`, which is the moment
48	 * there is nowhere left to report it.
49	 */
50	export function hasAgentDefinition(name: string, defDir: string): boolean {
51	  return name !== "" && existsSync(join(defDir, `${name}.md`));
52	}
53	
54	export function extractDirective(output: string, defDir: string): string {
55	  for (const rawLine of output.split("\n")) {
56	    for (const candidate of lineForms(rawLine)) {
57	      const match = COMMAND_RE.exec(candidate);
58	      if (match) {
59	        const agent = match[1]!;
60	        if (hasAgentDefinition(agent, defDir)) return agent;
61	      }
62	    }
63	  }
64	  return "";
65	}
66	
