68	  const { values } = parseArgs({
69	    args: Bun.argv.slice(2),
70	    options: {
71	      "output-file": { type: "string" },
72	      "def-dir": { type: "string" },
73	    },
74	  });
75	  if (!values["output-file"] || !values["def-dir"]) {
76	    console.error("usage: extract_directive.ts --output-file FILE --def-dir DIR");
77	    process.exit(2);
78	  }
79	
80	  const output = existsSync(values["output-file"]) ? readFileSync(values["output-file"], "utf8") : "";
81	  const directive = extractDirective(output, values["def-dir"]);
